function exfail($m,$s=400){http_response_code($s);header('Content-Type:application/json;charset=utf-8');echo json_encode(['error'=>$m],JSON_UNESCAPED_UNICODE);exit;}function exuser(){global $C;$h=$_SERVER['HTTP_AUTHORIZATION']??'';if(!preg_match('/Bearer\s+(.+)/i',$h,$m))exfail('توکن نامعتبر است',401);$p=Jwt::verify(trim($m[1]),$C['jwt_secret']);if(!$p)exfail('نشست منقضی یا نامعتبر است',401);$u=Db::one("SELECT u.id,u.is_active,r.title role_title,r.is_admin FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?",[$p['sub']]);if(!$u||!$u['is_active'])exfail('کاربر نامعتبر است',401);if(empty($u['is_admin'])&&!in_array($u['role_title']??'', ['مدیر کل','رییس اداره بازرسی','نیروی اداری ارشد'],true))exfail('دسترسی خروجی خطوط و ایستگاه‌ها ندارید',403);return $u;}function xe($v){return htmlspecialchars((string)($v??''),ENT_XML1|ENT_QUOTES,'UTF-8');}function col($n){$s='';do{$s=chr(65+$n%26).$s;$n=intdiv($n,26)-1;}while($n>=0);return $s;}function cstr($r,$v,$s=0){return '<c r="'.$r.'" t="inlineStr" s="'.$s.'"><is><t>'.xe($v).'</t></is></c>';}function cnum($r,$v){return '<c r="'.$r.'" t="n"><v>'.xe($v).'</v></c>';}function jal($v){try{$d=new DateTime((string)$v,new DateTimeZone('Asia/Tehran'));$y=(int)$d->format('Y')-1600;$m=(int)$d->format('n')-1;$day=(int)$d->format('j')-1;$md=[31,28,31,30,31,30,31,31,30,31,30,31];$gy=$y+1600;$md[1]=((($gy%4===0)&&($gy%100!==0))||$gy%400===0)?29:28;$n=365*$y+intdiv($y+3,4)-intdiv($y+99,100)+intdiv($y+399,400);for($i=0;$i<$m;$i++)$n+=$md[$i];$n+=$day;$j=$n-79;$p=intdiv($j,12053);$j%=12053;$jy=979+33*$p+4*intdiv($j,1461);$j%=1461;if($j>=366){$jy+=intdiv($j-1,365);$j=($j-1)%365;}$jm=$j<186?1+intdiv($j,31):7+intdiv($j-186,30);$jd=1+($j<186?$j%31:($j-186)%30);return sprintf('%04d/%02d/%02d %s',$jy,$jm,$jd,$d->format('H:i:s'));}catch(Throwable $e){return (string)$v;}}
